//! The Biology panel's three shaders (`UI/InternalsSections`, `UI/InternalsPreview`, `UI/StomachAcid`), run on the CPU.
//!
//! These are the game's own pixel programs, translated mechanically from their compiled form by `tools/unity/dxbc_to_rust.py`
//! (disassemble with `tools/unity/shader_asm.py` and the hex-literal flag): nothing here was re-derived by hand, so the picture is the game's.
//! Registers hold raw bits, as on the GPU.
//!
//! To regenerate one: `shader_asm.py <asset> <path id> <prefix>`, then `dxbc_to_rust.py <prefix>_1.asm.txt <fn>` (`dxbc_to_rust_tex.py` for the
//! programs that read textures), then `splice_shader.py internals_shaders.rs <fn> <output>`. The organ map is checked cell by cell against the
//! game's GPU (`internals::tests::the_organ_map_is_what_the_games_gpu_makes`).

#![allow(warnings, clippy::all)]

fn f(x: u32) -> f32 {
    f32::from_bits(x)
}
fn b(x: f32) -> u32 {
    x.to_bits()
}
/// HLSL `saturate`: NaN gives 0.
fn sat(x: f32) -> f32 {
    if x.is_nan() { 0.0 } else { x.clamp(0.0, 1.0) }
}
/// HLSL `max` / `min` ignore a NaN operand.
fn fmax(a: f32, c: f32) -> f32 {
    if a.is_nan() { c } else if c.is_nan() { a } else if a > c { a } else { c }
}
fn fmin(a: f32, c: f32) -> f32 {
    if a.is_nan() { c } else if c.is_nan() { a } else if a < c { a } else { c }
}

